const ACTIVE_AD_CATEGORY_WHERE = {
  isActive: true,
  deletedAt: null,
};

const PUBLISHED_AD_WHERE = {
  isActive: true,
  deletedAt: null,
  status: AdStatus.PUBLISHED,
};

const SORT_FIELD_WHITELIST = new Set<AdSortField>([
